while
while (condicao) {
    // repete enquanto condicao for verdadeira
}

Exemplo:
int i = 0;
while (i &lt; 3) {
    i = i + 1;
    printf("%d\n", i);
}


1
2
3

Pós-incremento
Qual é a saída?
int i = 0;
while (i &lt; 3) {
    printf("%d\n", i++);
}

0
1
2

Pré-incremento
Qual é a saída?
int i = 0;
while (i &lt; 3) {
    printf("%d\n", ++i);
}

1
2
3

do while
do {
    // executa pelo menos uma vez
} while (condicao);
Semelhante ao while(), mas a condição de saída é avaliada ao final do laço

A diferença principal é que o bloco de código é executado pelo menos uma vez


Exemplo:
int i = 0;
do {
    printf("%d ", i);
    i++;
} while (i &lt; 3);
//0 1 2

for
for (inicializacao; condicao; passo) {
    // corpo do laço
}


inicialização: Executado apenas antes da primeira iteração
condição: Caso falhe, o laço para

Na primeira iteração é executado depois da inicialização

passo: Executado após cada execução do corpo, mas antes de testar condição

for
for (inicializacao; condicao; passo) {
    // corpo do laço
}
Exemplo:
for (int i = 0; i &lt; 3; i++) {
    printf("%d\n", i);
}

0
1
2

Exponenciação em C
#include &lt;stdio.h&gt;

int main() {
    int a, b, i, produto = 1;
    scanf("%d", &a);
    scanf("%d", &b);

    for (i = 0; i &lt; b; i++) {
        produto = a * produto;
    }

    return produto;
}

Conversão de tipo: primeiro exemplo
Qual é a saída?
#include &lt;stdio.h&gt;

int main() {
    float num;

    num = 4 / 2;
    // %.2f imprime só 2 casas decimais
    printf("%.2f\n", num); 

    num = 10 / 2.5;
    printf("%.2f\n", num);

    return 0;
}

2.00
4.00

Inteiros versus ponto flutuante
Qual é a saída?
#include &lt;stdio.h&gt;

int main() {
    float num;

    num = 4 / 2;
    printf("%.2f\n", num);

    num = 5 / 2;
    printf("%.2f\n", num);

    return 0;
}

2.00
2.00

Precedência do cast
Qual é a saída?
    float r1 = 7 / 2;
    float r2 = ((float) 7) / 2;
    float r3 = 7 / ((float) 2);
    float r4 = ((float) 7) / ((float) 2);
    float r5 = (float) 7 / 2;
    float r6 = (float) (7 / 2);

    printf("%.1f %.1f %.1f\n", r1, r2, r3);
    printf("%.1f %.1f %.1f\n", r4, r5, r6);

3.0 3.5 3.5
3.5 3.5 3.0
O cast tem precedência alta. Sem parênteses, vai normalmente ser executado primeiro.

Conversão de reais para inteiros
#include &lt;stdio.h&gt;

int main() {
    float f1 = 2.782;
    int n2 = f1;

    printf("%d\n", n2);
    return 0;
}

2

A parte fracionária é descartada!.

Conversão unsigned para a versão com sinal
int main( ) {
    int a = -1;
    unsigned int b = a;

    printf("a = %d\n", a);
    printf("b = %u\n", b);

    return 0;
}

Saída:
a = -1
b = 4294967295

Conversão implicita de int para unsigned
Cuidado: em expressões, C pode converter implicitamente um valor int para unsigned int, produzindo resultados inesperados.
int main() {
    int a = -1;
    unsigned int b = 1;

    if (a &lt; b) {
        printf("menor\n");
    } else {
        printf("maior ou igual\n");
    }
}

Saída: maior ou igual.

Na conversão para unsigned int, o valor -1 virou um positivo grande.

Sempre inicialize variáveis
Quando uma variável local é declarada, o programa reserva espaço de memória para ela.
Esse espaço não é necessariamente inicializado.

#include &lt;stdio.h&gt;

int main() {
    int num;
    printf("%d\n", num);
    return 0;
}
O programa pode imprimir um valor arbitrário.

Leitura de n elementos
#include &lt;stdio.h&gt;

int main() {
    int qtd;
    scanf("%d", &qtd);

    for (int i = 0; i &lt; qtd; i++) {
        int numero;
        scanf("%d", &numero);

        // Faz alguma coisa com numero
        printf("Leu numero!\n");
    }

    printf("Saiu!\n");
    return 0;
}

Leitura até sentinela
#include &lt;stdio.h&gt;

int main() {
    int numero;
    scanf("%d", &numero);

    while (numero &gt;= 0) {
        // Faz alguma coisa com numero
        printf("Leu numero!\n");
        scanf("%d", &numero);
    }

    printf("Saiu!\n");
    return 0;
}
Aqui, um número negativo encerra a leitura.

Exercício 5 – Menu de operações
Faça um programa com um menu de operações.
O programa deve ler um código:

1: soma dois números;
2: soma três números;
3: multiplica dois números;
0: sair.

Se o usuário escolher sair, o programa imprime o menor resultado obtido e encerra.
Caso contrário, lê os números necessários, imprime o resultado da operação e volta ao menu.

